import socket
# let's scan all IPs 172.27.0.1 to 172.27.0.254 on ports [80, 8080, 8081, 5000, 3000, 8000, 8888]
from concurrent.futures import ThreadPoolExecutor

def scan(ip, port):
    s = socket.socket()
    s.settimeout(0.1)
    try:
        s.connect((ip, port))
        return (ip, port)
    except:
        return None
    finally:
        s.close()

targets = [(f'172.27.0.{i}', p) for i in range(1, 20) for p in [80, 8080, 8081, 5000, 3000, 8000, 8888, 53]]
with ThreadPoolExecutor(max_workers=50) as ex:
    for res in ex.map(lambda x: scan(*x), targets):
        if res:
            print('Found:', res)
